        OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC);
        Map<String, Object> future = couponBody("FUTURE", "FIXED", 100);
        future.put("validFrom", now.plusDays(1).toString());
        future.put("validUntil", now.plusDays(2).toString());
