    @Test
    @DisplayName("R4.2 결제도 같은 키면 PG를 다시 부르지 않고 최초 응답을 돌려준다")
    void replaysPay() {
        long p = createProduct(1000, 10);
        long orderId = placeOrderOk("u1", null, p, 1);
        String key = newKey();

        Resp first = pay(orderId, key, "card-1");
