        api.post("/api/orders/" + cancelled + "/cancel", null);

        assertProblem(pay(paid), 409, "INVALID_STATE");
        assertProblem(pay(cancelled), 409, "INVALID_STATE");
        assertProblem(pay(777_777), 404, "ORDER_NOT_FOUND");
